const raw = $input.first().json.body;
const { action, type, by, data, change } = raw;

const COLORS = {
  create: 5763719,
  delete: 15548997,
  change: 5793266,
  comment: 16705372
};

const TYPE_LABELS = {
  userstory: 'Historia de usuario',
  issue: 'Incidencia',
  task: 'Tarea',
  milestone: 'Hito',
  wikipage: 'Página Wiki'
};

const TAIGA_BASE = 'https://taiga.ewcam.co';

const DISCORD_WEBHOOKS = {
  'Nuevo SIGW':     '__WEBHOOK-URL__',
  'Soporte':        '__WEBHOOK-URL__',
  'Desarrollo':     '__WEBHOOK-URL__',
  'GESTIÓN HUMANA': '__WEBHOOK-URL__',
  'Contabilidad':   '__WEBHOOK-URL__',
  'Tienda Webcam':  '__WEBHOOK-URL__',
  'Tesoreria':      '__WEBHOOK-URL__',
  'Fotografia':     '__WEBHOOK-URL__',
  'Asesores':       '__WEBHOOK-URL__',
  'Marketing':      '__WEBHOOK-URL__',
  '_default':       '__WEBHOOK-URL__'
};

const discordUrl = DISCORD_WEBHOOKS[data?.project?.name] || DISCORD_WEBHOOKS['_default'];

const typeLabel = TYPE_LABELS[type] || type;
const actor = by?.full_name || by?.username || 'Desconocido';
const subject = data?.subject || data?.name || 'Sin título';
const isComment = action === 'change' && change?.comment;

let color, title, description = '';

if (action === 'create') {
  color = COLORS.create;
  title = `✅ ${typeLabel} creado: ${subject}`;
  description = data?.description ? data.description.substring(0, 300) : '';
} else if (action === 'delete') {
  color = COLORS.delete;
  title = `🗑️ ${typeLabel} eliminado: ${subject}`;
} else if (isComment) {
  color = COLORS.comment;
  title = `💬 Comentario en ${typeLabel}: ${subject}`;
  description = change.comment.substring(0, 1000);
} else if (action === 'change') {
  color = COLORS.change;
  title = `✏️ ${typeLabel} actualizado: ${subject}`;
  const diffs = change?.diff || {};
  const lines = Object.entries(diffs).map(([k, v]) =>
    v.from !== undefined
      ? `**${k}**: ~~${String(v.from)}~~ → ${String(v.to)}`
      : `**${k}** modificado`
  );
  description = lines.join('\n') || 'Actualizado';
}

const fields = [];
if (data?.ref) fields.push({ name: 'Referencia', value: `#${data.ref}`, inline: true });
if (data?.status?.name) fields.push({ name: 'Estado', value: data.status.name, inline: true });
if (data?.assigned_to?.full_name) fields.push({ name: 'Asignado a', value: data.assigned_to.full_name, inline: true });
if (data?.project?.name) fields.push({ name: 'Proyecto', value: data.project.name, inline: true });

const url = data?.permalink || data?.project?.permalink || TAIGA_BASE;

fields.push({ name: 'Enlace', value: `[Ver en Taiga](${url})`, inline: false });

const embed = {
  title: title?.substring(0, 256),
  color,
  fields,
  footer: { text: `Por ${actor}` },
  timestamp: new Date().toISOString()
};

if (description) embed.description = description.substring(0, 4096);
if (url) embed.url = url;

return [{ json: { discordUrl, embeds: [embed] } }];
